	/** 
	 * updating a TrainingCourse.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a TrainingCourse." );

		StringBuilder msg = new StringBuilder( "Failed to update a TrainingCourse : " );        
		TrainingCourse entity = read();
		UpdateTrainingCourseCommand command = generateUpdateCommand();
		command.setTrainingCourseId(entity.getTrainingCourseId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created TrainingCourse." );

			// for use later on...
			trainingCourseId = entity.getTrainingCourseId();

			TrainingCourseService proxy = TrainingCourseService.getTrainingCourseInstance();  

			proxy.updateTrainingCourse( command ).get();

			LOGGER.info( "-- Successfully saved TrainingCourse - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + trainingCourseId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a TrainingCourse.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created TrainingCourse." );

		TrainingCourse entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read TrainingCourse with id " + trainingCourseId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read TrainingCourse with id " + trainingCourseId );

			throw e;
		}

		try{
			TrainingCourseService.getTrainingCourseInstance().delete( new DeleteTrainingCourseCommand( entity.getTrainingCourseId() ) ).get();
			LOGGER.info( "-- Successfully deleted TrainingCourse with id " + trainingCourseId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete TrainingCourse with id " + trainingCourseId );

			throw e;
		}
	}

